class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = () => ({ t: 'table', map: new Map(), header: false })

function cmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const p = x[i].codePointAt(0), q = y[i].codePointAt(0)
    if (p !== q) return p - q
  }
  return x.length - y.length
}

const isWs = (c) => c === ' ' || c === '\t'
const BARE = /[A-Za-z0-9_-]/
const join = (p, k) => (p === '' ? k : p + '.' + k)

class Parser {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (this.i < this.s.length && isWs(this.s[this.i])) this.i++ }
  atEnd() {
    this.ws()
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  peek() { return this.s[this.i] }

  name() {
    const c = this.peek()
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = []
    this.ws()
    parts.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; break }
    }
    return parts
  }
  basic() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.s[this.i++]
      const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(m, e)) out += m[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i - 1)))
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }

  value(path) {
    if (this.atEnd()) fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D})?(?:[eE][+-]?${D})?$`).test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
  array(path) {
    this.i++
    const items = []
    for (;;) {
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') { this.i++; break }
      items.push(this.value(path + '[' + items.length + ']'))
      if (this.atEnd()) fail('unterminated array')
      const c = this.peek()
      if (c === ',') { this.i++; continue }
      if (c === ']') { this.i++; break }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  inline(path) {
    this.i++
    const tbl = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      if (this.atEnd()) fail('unterminated inline table')
      const parts = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(join(path, parts.join('.')))
      assign(tbl, path, parts, v)
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') { this.i++; continue }
      if (c === '}') { this.i++; break }
      fail('unterminated inline table')
    }
    return tbl
  }
}

// Walk through name `k` inside table `tbl`, creating tables as needed.
function step(tbl, path, k) {
  const p = join(path, k)
  let n = tbl.map.get(k)
  if (!n) { n = newTable(); tbl.map.set(k, n) }
  if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
  if (n.t !== 'table') fail(p + ' is not a table')
  return [n, p]
}

function assign(tbl, path, parts, v) {
  let cur = tbl, p = path
  for (let j = 0; j < parts.length - 1; j++) [cur, p] = step(cur, p, parts[j])
  const k = parts[parts.length - 1]
  if (cur.map.has(k)) fail('key ' + join(p, k) + ' is defined twice')
  cur.map.set(k, v)
}

function parseDoc(text) {
  const root = newTable()
  let cur = root, curPath = ''
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const line = lines[ln]
      const P = new Parser(line)
      P.ws()
      const c = P.peek()
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        P.i++
        const aot = P.peek() === '['
        if (aot) P.i++
        const parts = P.dotted()
        P.ws()
        const close = (ch) => {
          if (P.peek() !== ch) fail('unterminated table header')
          P.i++
        }
        close(']')
        if (aot) close(']')
        if (!P.atEnd()) fail('trailing text after a table header')
        let t = root, p = ''
        for (let j = 0; j < parts.length - 1; j++) [t, p] = step(t, p, parts[j])
        const k = parts[parts.length - 1]
        const fp = join(p, k)
        const ex = t.map.get(k)
        if (aot) {
          if (!ex) {
            const nt = newTable()
            t.map.set(k, { t: 'array', items: [nt], aot: true })
            cur = nt
          } else if (ex.t === 'array' && ex.aot) {
            const nt = newTable()
            ex.items.push(nt)
            cur = nt
          } else fail(fp + ' is not an array of tables')
        } else if (!ex) {
          const nt = newTable()
          nt.header = true
          t.map.set(k, nt)
          cur = nt
        } else if (ex.t !== 'table') fail(fp + ' is not a table')
        else {
          if (ex.header) fail('table ' + fp + ' is defined twice')
          ex.header = true
          cur = ex
        }
        curPath = fp
        continue
      }
      const parts = P.dotted()
      P.ws()
      if (P.peek() !== '=') fail('expected key = value')
      P.i++
      const v = P.value(join(curPath, parts.join('.')))
      if (!P.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, parts, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${ln + 1}: ${e.message}`
      throw e
    }
  }
  return root
}

function toJs(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = [...n.map.keys()].sort(cmp)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJs(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJs(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of [...n.map.keys()].sort(cmp)) {
      const c = n.map.get(k), p = join(path, k)
      out.push(p + ' ' + c.t)
      keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      keys(c, p, out)
    })
  }
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let doc
try {
  doc = parseDoc(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (mode === 'json') process.stdout.write(toJs(doc, 0) + '\n')
else {
  const out = []
  keys(doc, '', out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

